package com.upc.computer.assistant.v2.runtime;

import org.apache.ibatis.annotations.*;
import java.util.*;

/** Closed set of SELECT projections. No caller-provided SQL, identifiers or ordering. */
public interface NaturalBusinessReadMapper {
    String AUTH_FILTER = "<if test='customer != null'> AND <choose><when test=\"domain == 'ORDER'\">t.customer_name=#{customer}</when><when test=\"domain == 'AFTERSALES'\">t.record_id IN (SELECT case_id FROM after_sales_case WHERE customer_name=#{customer}) AND (t.order_id IS NULL OR t.order_id IN (SELECT order_id FROM customer_order WHERE customer_name=#{customer}))</when><otherwise>1=0</otherwise></choose></if>"
        + "<if test='operator != null'> AND <choose><when test=\"domain == 'PRODUCTION'\">t.record_id IN (SELECT work_order_id FROM dispatch_task WHERE operator_id=#{operator})</when><when test=\"domain == 'ALARMS'\">t.work_order_id IN (SELECT work_order_id FROM dispatch_task WHERE operator_id=#{operator})</when><otherwise>1=0</otherwise></choose></if>";
    String SOURCE = "<choose>"
        + "<when test=\"domain == 'INVENTORY'\">SELECT v.inventory_id AS record_id,v.material_id,m.material_code,m.material_name,m.unit,v.warehouse_code,v.location_code,v.batch_no,v.quantity_on_hand,v.quantity_reserved,v.quantity_available,v.inventory_status AS status,v.updated_at AS event_at,CONCAT_WS(' ',m.material_code,m.material_name) AS search_text FROM inventory v LEFT JOIN material m ON m.material_id=v.material_id <if test='id != null'>WHERE v.material_id IN (SELECT material_id FROM customer_order_item WHERE order_id=#{id} UNION SELECT b.child_material_id FROM bom b JOIN customer_order_item i ON i.material_id=b.parent_material_id WHERE i.order_id=#{id})</if></when>"
        + "<when test=\"domain == 'PRODUCTION'\">SELECT w.work_order_id AS record_id,w.work_order_no,w.material_id,m.material_name,m.unit,w.planned_quantity,w.completed_quantity,w.qualified_quantity,w.unqualified_quantity,w.status,w.updated_at AS event_at,CONCAT_WS(' ',w.work_order_no,m.material_code,m.material_name) AS search_text FROM work_order w LEFT JOIN material m ON m.material_id=w.material_id <if test='id != null'>WHERE w.work_order_id IN " + com.upc.computer.assistant.v2.mapper.business.AiBusinessReadMapper.WORK_ORDERS + "</if></when>"
        + "<when test=\"domain == 'QUALITY'\">SELECT q.inspection_id AS record_id,q.inspection_no,q.material_id,m.material_name,m.unit,q.batch_no,q.sample_quantity,q.qualified_quantity,q.unqualified_quantity,q.inspection_result AS status,q.inspected_at AS event_at,CONCAT_WS(' ',q.inspection_no,m.material_code,m.material_name,q.batch_no) AS search_text FROM quality_inspection q LEFT JOIN material m ON m.material_id=q.material_id <if test='id != null'>WHERE q.inspection_id IN " + com.upc.computer.assistant.v2.mapper.business.AiBusinessReadMapper.INSPECTIONS + "</if></when>"
        + "<when test=\"domain == 'EQUIPMENT'\">SELECT e.equipment_id AS record_id,e.equipment_code,e.equipment_name,e.equipment_type,e.workshop,e.workstation,e.status,e.updated_at AS event_at,CONCAT_WS(' ',e.equipment_code,e.equipment_name,e.equipment_type) AS search_text FROM equipment e <if test='id != null'>WHERE e.equipment_id IN " + com.upc.computer.assistant.v2.mapper.business.AiBusinessReadMapper.EQUIPMENT + "</if></when>"
        + "<when test=\"domain == 'AFTERSALES'\">SELECT c.case_id AS record_id,c.case_no,c.order_id,c.material_id,m.material_name,c.problem_type,c.case_level,c.case_status AS status,c.opened_at AS event_at,CONCAT_WS(' ',c.case_no,c.problem_type,m.material_code,m.material_name) AS search_text FROM after_sales_case c LEFT JOIN material m ON m.material_id=c.material_id <if test='id != null'>WHERE c.case_id IN " + com.upc.computer.assistant.v2.mapper.business.AiBusinessReadMapper.CASES + "</if></when>"
        + "<when test=\"domain == 'MAINTENANCE'\">SELECT r.maintenance_id AS record_id,r.maintenance_no,r.equipment_id,e.equipment_code,e.equipment_name,r.maintenance_type,r.fault_description,r.maintenance_content,r.start_time,r.end_time,r.downtime_minutes,r.maintenance_result AS status,r.start_time AS event_at,CONCAT_WS(' ',r.maintenance_no,e.equipment_code,e.equipment_name,r.fault_description) AS search_text FROM equipment_maintenance_record r LEFT JOIN equipment e ON e.equipment_id=r.equipment_id</when>"
        + "<when test=\"domain == 'ALARMS'\">SELECT a.alarm_id AS record_id,a.alarm_no,a.equipment_id,e.equipment_code,e.equipment_name,a.work_order_id,a.alarm_type,a.alarm_level,a.alarm_description,a.alarm_status AS status,a.reported_at AS event_at,a.closed_at,CONCAT_WS(' ',a.alarm_no,e.equipment_code,e.equipment_name,a.alarm_description) AS search_text FROM andon_alarm a LEFT JOIN equipment e ON e.equipment_id=a.equipment_id</when>"
        + "<when test=\"domain == 'STOCK_MOVEMENT'\">SELECT t.transaction_id AS record_id,t.transaction_no,t.inventory_id,t.material_id,m.material_code,m.material_name,m.unit,t.transaction_type AS status,t.quantity,t.warehouse_code,t.location_code,t.batch_no,t.related_purchase_order_id,t.related_work_order_id,t.handled_at AS event_at,CONCAT_WS(' ',t.transaction_no,m.material_code,m.material_name,t.batch_no) AS search_text FROM inventory_transaction t LEFT JOIN material m ON m.material_id=t.material_id</when>"
        + "<otherwise>SELECT o.order_id AS record_id,o.order_no,o.customer_name,o.audit_status AS status,o.order_date AS event_at,o.required_delivery_date,o.order_no AS search_text FROM customer_order o <if test='id != null'>WHERE o.order_id=#{id}</if></otherwise></choose>";
    String FILTER = " WHERE 1=1 <if test='keyword != null'>AND LOCATE(#{keyword},t.search_text)>0</if><if test='start != null'>AND t.event_at &gt;= #{start} AND t.event_at &lt; #{end}</if>";

    @Select("<script>SELECT t.* FROM (" + SOURCE + ") t" + FILTER + " ORDER BY t.record_id</script>")
    List<Map<String,Object>> rows(@Param("domain") String domain,@Param("id") Long id,@Param("keyword") String keyword,@Param("start") String start,@Param("end") String end);
    @Select("<script>SELECT COUNT(*) FROM (" + SOURCE + ") t" + FILTER + "</script>")
    long count(@Param("domain") String domain,@Param("id") Long id,@Param("keyword") String keyword,@Param("start") String start,@Param("end") String end);
    String EXACT_FILTER = "<if test='selectors.warehouse_code != null'> AND t.warehouse_code=#{selectors.warehouse_code}</if>"
        + "<if test='selectors.location_code != null'> AND t.location_code=#{selectors.location_code}</if>"
        + "<if test='selectors.customer_name != null'> AND t.customer_name=#{selectors.customer_name}</if>"
        + "<if test='selectors.customer_names != null'> AND t.customer_name IN <foreach collection=\"@com.upc.computer.assistant.v2.runtime.BusinessSelectors@customerNames(selectors.customer_names)\" item='customer' open='(' separator=',' close=')'>#{customer}</foreach></if>"
        + "<if test='selectors.warehouse_codes != null'> AND t.warehouse_code IN <foreach collection=\"selectors.warehouse_codes.split(',')\" item='code' open='(' separator=',' close=')'>#{code}</foreach></if>"
        + "<if test='selectors.location_codes != null'> AND t.location_code IN <foreach collection=\"selectors.location_codes.split(',')\" item='code' open='(' separator=',' close=')'>#{code}</foreach></if>"
        + "<if test='selectors.excluded_warehouse_codes != null'> AND t.warehouse_code NOT IN <foreach collection=\"selectors.excluded_warehouse_codes.split(',')\" item='code' open='(' separator=',' close=')'>#{code}</foreach></if>"
        + "<if test='selectors.excluded_location_codes != null'> AND t.location_code NOT IN <foreach collection=\"selectors.excluded_location_codes.split(',')\" item='code' open='(' separator=',' close=')'>#{code}</foreach></if>";
    @Select("<script>SELECT t.* FROM (" + SOURCE + ") t" + FILTER + EXACT_FILTER + " ORDER BY t.record_id</script>")
    List<Map<String,Object>> rowsScoped(@Param("domain") String domain,@Param("id") Long id,@Param("keyword") String keyword,@Param("start") String start,@Param("end") String end,@Param("selectors") Map<String,String> selectors);
    @Select("<script>SELECT COUNT(*) FROM (" + SOURCE + ") t" + FILTER + EXACT_FILTER + "</script>")
    long countScoped(@Param("domain") String domain,@Param("id") Long id,@Param("keyword") String keyword,@Param("start") String start,@Param("end") String end,@Param("selectors") Map<String,String> selectors);
    @Select("<script>SELECT t.* FROM ("+SOURCE+") t"+FILTER+EXACT_FILTER+AUTH_FILTER+" ORDER BY t.record_id</script>")
    List<Map<String,Object>> rowsAuthorized(@Param("domain") String domain,@Param("id") Long id,@Param("keyword") String keyword,@Param("start") String start,@Param("end") String end,@Param("selectors") Map<String,String> selectors,@Param("customer") String customer,@Param("operator") Long operator);
    @Select("<script>SELECT COUNT(*) FROM ("+SOURCE+") t"+FILTER+EXACT_FILTER+AUTH_FILTER+"</script>")
    long countAuthorized(@Param("domain") String domain,@Param("id") Long id,@Param("keyword") String keyword,@Param("start") String start,@Param("end") String end,@Param("selectors") Map<String,String> selectors,@Param("customer") String customer,@Param("operator") Long operator);
    @Select("<script>SELECT order_id,order_no FROM customer_order WHERE 1=1 <if test='id != null'>AND order_id=#{id}</if><if test='number != null'>AND order_no=#{number}</if><if test='customer != null'>AND customer_name=#{customer}</if> ORDER BY order_id LIMIT 2</script>")
    List<Map<String,Object>> resolveCustomerOrder(@Param("id") Long id,@Param("number") String number,@Param("customer") String customer);
    @Select("<script>SELECT w.work_order_id,w.work_order_no FROM work_order w WHERE (w.work_order_no=#{reference} OR (#{reference} REGEXP '^[0-9]+$' AND (CAST(w.work_order_id AS CHAR)=#{reference} OR RIGHT(w.work_order_no,CHAR_LENGTH(#{reference}))=#{reference}))) <if test='operator != null'>AND EXISTS (SELECT 1 FROM dispatch_task d WHERE d.work_order_id=w.work_order_id AND d.operator_id=#{operator})</if> ORDER BY w.work_order_id LIMIT 9</script>")
    List<Map<String,Object>> resolveWorkOrders(@Param("reference") String reference,@Param("operator") Long operator);
    @Select("<script>SELECT w.work_order_id AS record_id,w.work_order_no,w.material_id,m.material_name,m.unit,w.planned_quantity,w.completed_quantity,w.qualified_quantity,w.unqualified_quantity,w.status,w.updated_at AS event_at FROM work_order w LEFT JOIN material m ON m.material_id=w.material_id WHERE w.work_order_id=#{id}<if test='operator != null'> AND EXISTS (SELECT 1 FROM dispatch_task d WHERE d.work_order_id=w.work_order_id AND d.operator_id=#{operator})</if><if test='start != null'> AND w.updated_at &gt;=#{start} AND w.updated_at &lt;#{end}</if></script>")
    List<Map<String,Object>> workOrderRows(@Param("id") long id,@Param("operator") Long operator,@Param("start") String start,@Param("end") String end);
    @Select("<script>SELECT d.dispatch_id,d.dispatch_no,d.work_order_id,d.step_id,s.step_no,s.step_name,d.operator_id,u.real_name AS operator_name,d.equipment_id,d.assigned_quantity,d.accepted_quantity,d.completed_quantity,d.assigned_at,d.accepted_at,d.status FROM dispatch_task d LEFT JOIN process_step s ON s.step_id=d.step_id LEFT JOIN `user` u ON u.user_id=d.operator_id WHERE d.work_order_id=#{id}<if test='operator != null'> AND d.operator_id=#{operator}</if> ORDER BY s.step_no,d.dispatch_id</script>")
    List<Map<String,Object>> workOrderDispatch(@Param("id") long id,@Param("operator") Long operator);
    @Select("<script>SELECT i.order_item_id, i.order_id, i.material_id, i.product_name, i.quantity, i.unit, m.unit AS material_unit, i.delivery_date, i.item_status, i.updated_at FROM customer_order_item i LEFT JOIN material m ON m.material_id=i.material_id WHERE i.order_id IN <foreach collection='ids' item='orderId' open='(' separator=',' close=')'>#{orderId}</foreach> <if test='customer != null'>AND i.order_id IN (SELECT order_id FROM customer_order WHERE customer_name=#{customer})</if> ORDER BY i.order_item_id</script>")
    List<Map<String,Object>> riskLines(@Param("ids") List<Long> ids,@Param("customer") String customer);
    @Select("<script>SELECT d.delivery_id, d.order_id, d.material_id, d.work_order_id, d.batch_no, d.delivery_quantity, d.delivery_date, d.delivery_status, d.updated_at, CASE WHEN p.order_item_id=i.order_item_id AND w.material_id=d.material_id AND p.material_id=d.material_id AND pp.source_order_id=d.order_id AND w.plan_id=p.plan_id THEN p.order_item_id END AS mapped_order_item_id, CASE WHEN d.work_order_id IS NOT NULL AND (w.work_order_id IS NULL OR p.plan_item_id IS NULL OR w.plan_id IS NULL OR w.plan_id&lt;&gt;p.plan_id OR i.order_item_id IS NULL OR w.material_id&lt;&gt;d.material_id OR p.material_id&lt;&gt;d.material_id OR pp.source_order_id IS NULL OR pp.source_order_id&lt;&gt;d.order_id) THEN 'INVALID' ELSE 'RECORDED' END AS mapping_status FROM delivery_order d LEFT JOIN work_order w ON w.work_order_id=d.work_order_id LEFT JOIN production_plan_item p ON p.plan_item_id=w.plan_item_id LEFT JOIN production_plan pp ON pp.plan_id=p.plan_id LEFT JOIN customer_order_item i ON i.order_item_id=p.order_item_id AND i.order_id=d.order_id AND i.material_id=d.material_id WHERE d.order_id IN <foreach collection='ids' item='orderId' open='(' separator=',' close=')'>#{orderId}</foreach> <if test='customer != null'>AND d.order_id IN (SELECT order_id FROM customer_order WHERE customer_name=#{customer})</if> ORDER BY d.delivery_id</script>")
    List<Map<String,Object>> riskDeliveries(@Param("ids") List<Long> ids,@Param("customer") String customer);
    @Select("<script>SELECT p.source_order_id AS order_id,o.order_no,o.audit_status AS order_status,p.plan_id,p.plan_no,p.plan_status,p.version_no AS plan_version,p.parent_plan_no,pi.plan_item_id,pi.order_item_id,pi.material_id,m.unit AS material_unit,i.unit AS order_unit,pi.planned_quantity,pi.completed_quantity,pi.item_status,COALESCE(i.delivery_date,o.required_delivery_date) AS due_date,CASE WHEN i.order_id=p.source_order_id AND i.material_id=pi.material_id THEN 'LINKED' ELSE 'UNVERIFIED' END AS mapping_status FROM production_plan p JOIN production_plan_item pi ON pi.plan_id=p.plan_id JOIN customer_order o ON o.order_id=p.source_order_id LEFT JOIN customer_order_item i ON i.order_item_id=pi.order_item_id LEFT JOIN material m ON m.material_id=pi.material_id WHERE p.source_order_id IN <foreach collection='ids' item='selectedId' open='(' separator=',' close=')'>#{selectedId}</foreach> ORDER BY p.plan_id,pi.plan_item_id</script>")
    List<Map<String,Object>> resourcePlans(@Param("ids") List<Long> ids);
    @Select("<script>SELECT p.source_order_id AS order_id,o.order_no,o.audit_status AS order_status,p.plan_status,w.work_order_id,w.work_order_no,w.plan_id,w.plan_item_id,w.material_id,w.planned_quantity,w.completed_quantity,w.status,w.route_id,CASE WHEN w.plan_id=pi.plan_id AND pi.order_item_id=i.order_item_id AND i.order_id=p.source_order_id AND w.material_id=pi.material_id AND pi.material_id=i.material_id THEN 'LINKED' ELSE 'UNVERIFIED' END AS mapping_status FROM work_order w JOIN production_plan p ON p.plan_id=w.plan_id JOIN customer_order o ON o.order_id=p.source_order_id LEFT JOIN production_plan_item pi ON pi.plan_item_id=w.plan_item_id LEFT JOIN customer_order_item i ON i.order_item_id=pi.order_item_id WHERE p.source_order_id IN <foreach collection='ids' item='selectedId' open='(' separator=',' close=')'>#{selectedId}</foreach> ORDER BY w.work_order_id</script>")
    List<Map<String,Object>> resourceWorks(@Param("ids") List<Long> ids);
    @Select("<script>SELECT p.source_order_id AS order_id,o.order_no,o.audit_status AS order_status,p.plan_status,s.schedule_id,s.plan_id,s.step_id,s.step_no,s.step_name,s.equipment_id,s.equipment_code,s.planned_start,s.planned_end,s.planned_quantity FROM production_plan_schedule s JOIN production_plan p ON p.plan_id=s.plan_id JOIN customer_order o ON o.order_id=p.source_order_id WHERE p.source_order_id IN <foreach collection='ids' item='selectedId' open='(' separator=',' close=')'>#{selectedId}</foreach> ORDER BY s.schedule_id</script>")
    List<Map<String,Object>> resourceSchedules(@Param("ids") List<Long> ids);
    @Select("<script>SELECT p.source_order_id AS order_id,o.order_no,o.audit_status AS order_status,p.plan_status,w.status AS work_status,w.plan_id,w.plan_item_id,d.dispatch_id,d.dispatch_no,d.work_order_id,d.step_id,d.operator_id,u.real_name AS operator_name,d.equipment_id,d.assigned_quantity,d.completed_quantity,d.status,d.assigned_at,CASE WHEN w.plan_id=pi.plan_id AND pi.material_id=w.material_id AND i.order_id=p.source_order_id AND i.material_id=w.material_id AND s.route_id=w.route_id THEN 'LINKED' ELSE 'UNVERIFIED' END AS mapping_status FROM dispatch_task d JOIN work_order w ON w.work_order_id=d.work_order_id JOIN production_plan p ON p.plan_id=w.plan_id JOIN customer_order o ON o.order_id=p.source_order_id LEFT JOIN production_plan_item pi ON pi.plan_item_id=w.plan_item_id LEFT JOIN customer_order_item i ON i.order_item_id=pi.order_item_id LEFT JOIN process_step s ON s.step_id=d.step_id LEFT JOIN `user` u ON u.user_id=d.operator_id WHERE p.source_order_id IN <foreach collection='ids' item='selectedId' open='(' separator=',' close=')'>#{selectedId}</foreach> ORDER BY d.dispatch_id</script>")
    List<Map<String,Object>> resourceDispatches(@Param("ids") List<Long> ids);
    @Select("<script>SELECT b.bom_id,b.parent_material_id,b.child_material_id,m.material_name,m.unit,b.quantity,b.loss_rate,b.version_no,b.effective_date,b.expire_date,b.status,CASE WHEN EXISTS (SELECT 1 FROM bom nested WHERE nested.parent_material_id=b.child_material_id AND nested.status=1 AND nested.effective_date&lt;=#{day} AND (nested.expire_date IS NULL OR nested.expire_date>=#{day})) THEN 1 ELSE 0 END AS has_child_bom FROM bom b LEFT JOIN material m ON m.material_id=b.child_material_id WHERE b.parent_material_id IN <foreach collection='ids' item='selectedId' open='(' separator=',' close=')'>#{selectedId}</foreach> ORDER BY b.bom_id</script>")
    List<Map<String,Object>> resourceBoms(@Param("ids") List<Long> ids,@Param("day") String day);
    @Select("<script>SELECT v.inventory_id,v.material_id,m.unit,v.warehouse_code,v.location_code,v.batch_no,v.quantity_on_hand,v.quantity_reserved,v.quantity_available,v.inventory_status FROM inventory v LEFT JOIN material m ON m.material_id=v.material_id WHERE v.material_id IN <foreach collection='ids' item='selectedId' open='(' separator=',' close=')'>#{selectedId}</foreach> ORDER BY v.inventory_id</script>")
    List<Map<String,Object>> resourceStock(@Param("ids") List<Long> ids);
    @Select("<script>SELECT p.source_order_id AS order_id,t.transaction_id,t.related_work_order_id,t.material_id,t.transaction_type,t.quantity,t.handled_at,CASE WHEN w.plan_id=pi.plan_id AND pi.material_id=w.material_id AND i.order_id=p.source_order_id AND i.material_id=w.material_id THEN 'LINKED' ELSE 'UNVERIFIED' END AS mapping_status FROM inventory_transaction t JOIN work_order w ON w.work_order_id=t.related_work_order_id JOIN production_plan p ON p.plan_id=w.plan_id LEFT JOIN production_plan_item pi ON pi.plan_item_id=w.plan_item_id LEFT JOIN customer_order_item i ON i.order_item_id=pi.order_item_id WHERE p.source_order_id IN <foreach collection='ids' item='selectedId' open='(' separator=',' close=')'>#{selectedId}</foreach> ORDER BY t.transaction_id</script>")
    List<Map<String,Object>> resourceIssues(@Param("ids") List<Long> ids);
}
